#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SearchMode {
    Simple,
    MatchCase,
    MatchWholeWord,
    MatchCaseWholeWord,
    Regex,
}
impl SearchMode {
    fn next(self) -> Self {
        match self {
            SearchMode::Simple => SearchMode::MatchCase,
            SearchMode::MatchCase => SearchMode::MatchWholeWord,
            SearchMode::MatchWholeWord => SearchMode::MatchCaseWholeWord,
            SearchMode::MatchCaseWholeWord => SearchMode::Regex,
            SearchMode::Regex => SearchMode::Simple,
        }
    }
    fn as_str(self) -> &'static str {
        match self {
            SearchMode::Simple => "Simple",
            SearchMode::MatchCase => "Match Case",
            SearchMode::MatchWholeWord => "Match Whole Word",
            SearchMode::MatchCaseWholeWord => "Match Case Whole Word",
            SearchMode::Regex => "Regex",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ReplaceMode {
    Simple,
    PreserveCase,
    DeleteLine,
}
impl ReplaceMode {
    fn next(self) -> Self {
        match self {
            ReplaceMode::Simple => ReplaceMode::PreserveCase,
            ReplaceMode::PreserveCase => ReplaceMode::DeleteLine,
            ReplaceMode::DeleteLine => ReplaceMode::Simple,
        }
    }
    fn as_str(self) -> &'static str {
        match self {
            ReplaceMode::Simple => "Simple",
            ReplaceMode::PreserveCase => "Preserve Case",
            ReplaceMode::DeleteLine => "Delete Line",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Focus {
    Search,
    Replace,
    ResultList,
}
impl Focus {
    fn next(self) -> Self {
        match self {
            Focus::Search => Focus::Replace,
            Focus::Replace => Focus::ResultList,
            Focus::ResultList => Focus::Search,
        }
    }
    fn prev(self) -> Self {
        match self {
            Focus::Search => Focus::ResultList,
            Focus::Replace => Focus::Search,
            Focus::ResultList => Focus::Replace,
        }
    }
}

#[derive(Debug, Clone)]
struct LineMatch {
    number: usize,
    content: String,
}

#[derive(Debug, Clone)]
struct FileResult {
    path: PathBuf, // relative
    lines: Vec<LineMatch>,
}

struct App {
    project_root: PathBuf,
    search_input: String,
    search_cursor: usize,
    replace_input: String,
    replace_cursor: usize,
    search_mode: SearchMode,
    replace_mode: ReplaceMode,
    focus: Focus,
    results: Vec<FileResult>,
    selected_file: usize,
    // when Some(idx), we are showing lines of that file
    expanded_file: Option<usize>,
    selected_line: usize,
    show_help: bool,
    help_tab: usize, // 0 global, 1 navigation
    show_confirm: bool,
    confirm_is_empty_replace: bool,
    confirm_selection: usize, // 0 continue, 1 cancel
    notification: Option<(String, Instant)>,
    should_quit: bool,
}

impl App {
    fn new(project_root: PathBuf) -> Self {
        Self {
            project_root,
            search_input: String::new(),
            search_cursor: 0,
            replace_input: String::new(),
            replace_cursor: 0,
            search_mode: SearchMode::Simple,
            replace_mode: ReplaceMode::Simple,
            focus: Focus::Search,
            results: Vec::new(),
            selected_file: 0,
            expanded_file: None,
            selected_line: 0,
            show_help: false,
            help_tab: 0,
            show_confirm: false,
            confirm_is_empty_replace: false,
            confirm_selection: 0,
            notification: None,
            should_quit: false,
        }
    }

    fn compile_search_regex(&self) -> Option<Regex> {
        let pat = self.search_input.as_str();
        if pat.is_empty() {
            return None;
        }
        let regex_str = match self.search_mode {
            SearchMode::Simple => format!("(?i){}", regex::escape(pat)),
            SearchMode::MatchCase => regex::escape(pat),
            SearchMode::MatchWholeWord => format!("(?i)\\b{}\\b", regex::escape(pat)),
            SearchMode::MatchCaseWholeWord => format!("\\b{}\\b", regex::escape(pat)),
            SearchMode::Regex => pat.to_string(),
        };
        Regex::new(&regex_str).ok()
    }

    fn perform_search(&mut self) {
        self.results.clear();
        self.selected_file = 0;
        self.expanded_file = None;
        self.selected_line = 0;
        if self.search_input.is_empty() {
            return;
        }
        let re = match self.compile_search_regex() {
            Some(r) => r,
            None => return, // invalid regex => no results
        };
        let walker = ignore::WalkBuilder::new(&self.project_root)
            .hidden(true)
            .git_ignore(true)
            .git_global(true)
            .git_exclude(true)
            .parents(true)
            .follow_links(false)
            .build();
        let mut results = Vec::new();
        for entry in walker {
            let entry = match entry {
                Ok(e) => e,
                Err(_) => continue,
            };
            if !entry.file_type().map(|ft| ft.is_file()).unwrap_or(false) {
                continue;
            }
            let path = entry.path();
            // read file
            let content = match fs::read_to_string(path) {
                Ok(c) => c,
                Err(_) => continue,
            };
            if content.contains('\0') {
                continue;
            }
            let mut line_matches = Vec::new();
            for (idx, line) in content.lines().enumerate() {
                if re.is_match(line) {
                    line_matches.push(LineMatch { number: idx+1, content: line.to_string() });
                }
            }
            if !line_matches.is_empty() {
                let rel = path.strip_prefix(&self.project_root).unwrap_or(path).to_path_buf();
                results.push(FileResult { path: rel, lines: line_matches });
            }
        }
        results.sort_by(|a,b| a.path.cmp(&b.path));
        self.results = results;
        // clamp selection
        if self.selected_file >= self.results.len() && !self.results.is_empty() {
            self.selected_file = self.results.len()-1;
        }
    }

    fn preserve_case(orig: &str, rep: &str) -> String {
        if orig.is_empty() || rep.is_empty() {
            return rep.to_string();
        }
        let is_all_upper = orig.chars().filter(|c| c.is_alphabetic()).all(|c| c.is_uppercase()) && orig.chars().any(|c| c.is_alphabetic());
        if is_all_upper {
            return rep.to_uppercase();
        }
        let mut chars = orig.chars();
        let first = chars.next().unwrap();
        let rest = &orig[first.len_utf8()..];
        let is_capitalized = first.is_uppercase() && rest.chars().filter(|c| c.is_alphabetic()).all(|c| c.is_lowercase());
        if is_capitalized {
            let mut rep_chars = rep.chars();
            if let Some(f) = rep_chars.next() {
                let first_up: String = f.to_uppercase().collect();
                let rest_low = rep_chars.as_str().to_lowercase();
                return format!("{}{}", first_up, rest_low);
            } else {
                return String::new();
            }
        }
        // default lower
        // if orig is all lower, keep rep as is (lower)
        // we return rep as is if it's already lower? But we normalize to lower to handle "hi" vs "HELLO"
        // If rep is lower, fine. If rep is mixed, we return lower?
        // For simplicity, if orig is lower, return rep as is (but lowercased if needed)
        // The observed behavior for "hello" -> "hi" produced "hi" lower, so return rep as is (assuming rep is lower)
        // We'll return rep.to_string() if orig is lower
        // But to be safe, return rep as is
        rep.to_string()
    }

    fn apply_replace_to_content(&self, content: &str) -> String {
        if self.search_input.is_empty() {
            return content.to_string();
        }
        let re = match self.compile_search_regex() {
            Some(r) => r,
            None => return content.to_string(),
        };
        match self.replace_mode {
            ReplaceMode::DeleteLine => {
                let mut out_lines = Vec::new();
                for line in content.lines() {
                    if !re.is_match(line) {
                        out_lines.push(line);
                    }
                }
                let mut out = out_lines.join("\n");
                if content.ends_with('\n') && !out.is_empty() {
                    out.push('\n');
                } else if content.is_empty() {
                    out = String::new();
                }
                // handle case where original had no newline but we joined with \n
                out
            },
            ReplaceMode::Simple => {
                let mut result = String::new();
                let mut last = 0;
                for mat in re.find_iter(content) {
                    result.push_str(&content[last..mat.start()]);
                    result.push_str(&self.replace_input);
                    last = mat.end();
                }
                result.push_str(&content[last..]);
                result
            },
            ReplaceMode::PreserveCase => {
                let mut result = String::new();
                let mut last = 0;
                for mat in re.find_iter(content) {
                    result.push_str(&content[last..mat.start()]);
                    let orig = mat.as_str();
                    let rep = Self::preserve_case(orig, &self.replace_input);
                    result.push_str(&rep);
                    last = mat.end();
                }
                result.push_str(&content[last..]);
                result
            }
        }
    }

    fn global_replace(&mut self) {
        // Check if search empty -> do nothing
        if self.search_input.is_empty() {
            return;
        }
        // if replace empty and mode not DeleteLine, we already have confirm
        let mut success_count = 0;
        // clone results to avoid borrow issues
        let results_clone = self.results.clone();
        for fr in &results_clone {
            let abs_path = self.project_root.join(&fr.path);
            let content = match fs::read_to_string(&abs_path) {
                Ok(c) => c,
                Err(_) => continue,
            };
            let new_content = self.apply_replace_to_content(&content);
            if new_content != content {
                if let Err(_) = fs::write(&abs_path, new_content) {
                    continue;
                }
                success_count += 1;
            }
        }
        // after global replace, clear inputs and results as observed
        self.search_input.clear();
        self.search_cursor = 0;
        self.replace_input.clear();
        self.replace_cursor = 0;
        self.results.clear();
        self.selected_file = 0;
        self.expanded_file = None;
        self.selected_line = 0;
        self.notification = Some(("Search and replace completed successfully".to_string(), Instant::now()));
        self.show_confirm = false;
    }

    fn replace_single_file(&mut self, idx: usize) {
        if idx >= self.results.len() { return; }
        let fr = self.results[idx].clone();
        let abs_path = self.project_root.join(&fr.path);
        let content = match fs::read_to_string(&abs_path) {
            Ok(c) => c,
            Err(_) => return,
        };
        let new_content = self.apply_replace_to_content(&content);
        if new_content != content {
            let _ = fs::write(&abs_path, new_content);
        }
        // remove from results or refresh
        self.results.remove(idx);
        if self.selected_file >= self.results.len() && self.selected_file > 0 {
            self.selected_file -= 1;
        }
        self.expanded_file = None;
        self.selected_line = 0;
        self.notification = Some(("File replacement completed successfully".to_string(), Instant::now()));
        // if after removal we have no results, stay
    }

    fn replace_single_line(&mut self, file_idx: usize, line_idx: usize) {
        if file_idx >= self.results.len() { return; }
        let fr = self.results[file_idx].clone();
        if line_idx >= fr.lines.len() { return; }
        let line_match = fr.lines[line_idx].clone();
        let abs_path = self.project_root.join(&fr.path);
        let content = match fs::read_to_string(&abs_path) {
            Ok(c) => c,
            Err(_) => return,
        };
        // For DeleteLine mode, we need to delete that line entirely (matching line)
        // Otherwise replace occurrences within that line only
        let re = match self.compile_search_regex() {
            Some(r) => r,
            None => return,
        };
        let mut lines: Vec<String> = content.lines().map(|s| s.to_string()).collect();
        let has_trailing_newline = content.ends_with('\n');
        // line numbers are 1-indexed
        let target_idx = line_match.number - 1;
        if target_idx >= lines.len() { return; }
        match self.replace_mode {
            ReplaceMode::DeleteLine => {
                lines.remove(target_idx);
            },
            ReplaceMode::Simple => {
                let line = &lines[target_idx];
                let mut new_line = String::new();
                let mut last = 0;
                for mat in re.find_iter(line) {
                    new_line.push_str(&line[last..mat.start()]);
                    new_line.push_str(&self.replace_input);
                    last = mat.end();
                }
                new_line.push_str(&line[last..]);
                lines[target_idx] = new_line;
            },
            ReplaceMode::PreserveCase => {
                let line = &lines[target_idx];
                let mut new_line = String::new();
                let mut last = 0;
                for mat in re.find_iter(line) {
                    new_line.push_str(&line[last..mat.start()]);
                    let rep = Self::preserve_case(mat.as_str(), &self.replace_input);
                    new_line.push_str(&rep);
                    last = mat.end();
                }
                new_line.push_str(&line[last..]);
                lines[target_idx] = new_line;
            }
        }
        let mut new_content = lines.join("\n");
        if has_trailing_newline && !new_content.is_empty() {
            new_content.push('\n');
        }
        let _ = fs::write(&abs_path, new_content);
        // Update results: remove that line
        self.results[file_idx].lines.remove(line_idx);
        if self.results[file_idx].lines.is_empty() {
            self.results.remove(file_idx);
            self.expanded_file = None;
            self.selected_line = 0;
            if self.selected_file >= self.results.len() && self.selected_file > 0 {
                self.selected_file -= 1;
            }
        } else {
            if self.selected_line >= self.results[file_idx].lines.len() && self.selected_line > 0 {
                self.selected_line -= 1;
            }
        }
        self.notification = Some(("Line replacement completed successfully".to_string(), Instant::now()));
    }

    fn handle_key(&mut self, key: event::KeyEvent) {
        // Global handling when help shown
        if self.show_help {
            match key.code {
                KeyCode::Esc | KeyCode::Char('q') | KeyCode::Char('Q') => {
                    self.show_help = false;
                    return;
                },
                KeyCode::Right | KeyCode::Tab => {
                    self.help_tab = (self.help_tab + 1) % 2;
                    return;
                },
                KeyCode::Left | KeyCode::BackTab => {
                    self.help_tab = if self.help_tab == 0 { 1 } else { 0 };
                    return;
                },
                _ => return,
            }
        }
        if self.show_confirm {
            match key.code {
                KeyCode::Esc => {
                    self.show_confirm = false;
                    return;
                },
                KeyCode::Enter => {
                    if self.confirm_selection == 0 {
                        self.global_replace();
                    } else {
                        self.show_confirm = false;
                    }
                    return;
                },
                KeyCode::Left | KeyCode::Char('h') if key.modifiers.is_empty() => {
                    self.confirm_selection = if self.confirm_selection == 0 { 1 } else { 0 };
                    return;
                },
                KeyCode::Right | KeyCode::Char('l') if key.modifiers.is_empty() => {
                    self.confirm_selection = if self.confirm_selection == 0 { 1 } else { 0 };
                    return;
                },
                KeyCode::Tab => {
                    self.confirm_selection = 1 - self.confirm_selection;
                    return;
                },
                KeyCode::BackTab => {
                    self.confirm_selection = 1 - self.confirm_selection;
                    return;
                },
                KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.should_quit = true;
                    return;
                },
                KeyCode::Char('d') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.should_quit = true;
                    return;
                },
                _ => return,
            }
        }

        // Global shortcuts
        if key.modifiers.contains(KeyModifiers::CONTROL) {
            match key.code {
                KeyCode::Char('c') | KeyCode::Char('d') => {
                    self.should_quit = true;
                    return;
                },
                KeyCode::Char('z') => {
                    // suspend
                    // We will handle suspend outside via flag? For now do inline disable
                    // To suspend, we need to leave raw mode; we'll set a flag and handle in main loop
                    // For simplicity, try to suspend here
                    let _ = disable_raw_mode();
                    let _ = execute!(io::stdout(), LeaveAlternateScreen);
                    let _ = nix::sys::signal::raise(nix::sys::signal::Signal::SIGTSTP);
                    let _ = enable_raw_mode();
                    let _ = execute!(io::stdout(), EnterAlternateScreen);
                    return;
                },
                KeyCode::Char('r') => {
                    self.perform_search();
                    return;
                },
                KeyCode::Char('o') => {
                    if !self.search_input.is_empty() {
                        // check if replace empty and mode not DeleteLine
                        if self.replace_input.is_empty() && self.replace_mode != ReplaceMode::DeleteLine {
                            self.confirm_is_empty_replace = true;
                        } else {
                            self.confirm_is_empty_replace = false;
                        }
                        self.show_confirm = true;
                        self.confirm_selection = 0;
                    }
                    return;
                },
                KeyCode::Char('b') => {
                    self.show_help = true;
                    self.help_tab = 0;
                    return;
                },
                KeyCode::Char('n') => {
                    match self.focus {
                        Focus::Search => {
                            self.search_mode = self.search_mode.next();
                            self.perform_search();
                        },
                        Focus::Replace => {
                            self.replace_mode = self.replace_mode.next();
                            // if switching to DeleteLine, maybe clear? But keep input
                        },
                        Focus::ResultList => {
                            // maybe do nothing? Original Ctrl-n when in ResultList does nothing? In earlier test it stayed same.
                        }
                    }
                    return;
                },
                _ => {}
            }
        }

        match self.focus {
            Focus::Search => {
                match key.code {
                    KeyCode::Tab => {
                        self.focus = self.focus.next();
                    },
                    KeyCode::BackTab => {
                        self.focus = self.focus.prev();
                    },
                    KeyCode::Enter => {
                        self.perform_search();
                    },
                    KeyCode::Backspace => {
                        if self.search_cursor > 0 {
                            let prev = self.search_input[..self.search_cursor].chars().next_back().map(|c| c.len_utf8()).unwrap_or(0);
                            let remove_at = self.search_cursor - prev;
                            self.search_input.remove(remove_at);
                            self.search_cursor = remove_at;
                            self.perform_search();
                        }
                    },
                    KeyCode::Delete => {
                        if self.search_cursor < self.search_input.len() {
                            let next_len = self.search_input[self.search_cursor..].chars().next().map(|c| c.len_utf8()).unwrap_or(0);
                            self.search_input.drain(self.search_cursor..self.search_cursor+next_len);
                            self.perform_search();
                        }
                    },
                    KeyCode::Left => {
                        if self.search_cursor > 0 {
                            let prev = self.search_input[..self.search_cursor].chars().next_back().map(|c| c.len_utf8()).unwrap_or(0);
                            self.search_cursor -= prev;
                        }
                    },
                    KeyCode::Right => {
                        if self.search_cursor < self.search_input.len() {
                            let next_len = self.search_input[self.search_cursor..].chars().next().map(|c| c.len_utf8()).unwrap_or(0);
                            self.search_cursor += next_len;
                        }
                    },
                    KeyCode::Home => {
                        self.search_cursor = 0;
                    },
                    KeyCode::End => {
                        self.search_cursor = self.search_input.len();
                    },
                    KeyCode::Char(c) => {
                        // ignore if ctrl
                        if !key.modifiers.contains(KeyModifiers::CONTROL) && !key.modifiers.contains(KeyModifiers::ALT) {
                            self.search_input.insert(self.search_cursor, c);
                            self.search_cursor += c.len_utf8();
                            self.perform_search();
                        }
                    },
                    KeyCode::Esc => {
                        // maybe clear? Not needed
                    },
                    _ => {}
                }
            },
            Focus::Replace => {
                match key.code {
                    KeyCode::Tab => {
                        self.focus = self.focus.next();
                    },
                    KeyCode::BackTab => {
                        self.focus = self.focus.prev();
                    },
                    KeyCode::Backspace => {
                        if self.replace_mode == ReplaceMode::DeleteLine {
                            return;
                        }
                        if self.replace_cursor > 0 {
                            let prev = self.replace_input[..self.replace_cursor].chars().next_back().map(|c| c.len_utf8()).unwrap_or(0);
                            let remove_at = self.replace_cursor - prev;
                            self.replace_input.remove(remove_at);
                            self.replace_cursor = remove_at;
                        }
                    },
                    KeyCode::Delete => {
                        if self.replace_mode == ReplaceMode::DeleteLine { return; }
                        if self.replace_cursor < self.replace_input.len() {
                            let next_len = self.replace_input[self.replace_cursor..].chars().next().map(|c| c.len_utf8()).unwrap_or(0);
                            self.replace_input.drain(self.replace_cursor..self.replace_cursor+next_len);
                        }
                    },
                    KeyCode::Left => {
                        if self.replace_cursor > 0 {
                            let prev = self.replace_input[..self.replace_cursor].chars().next_back().map(|c| c.len_utf8()).unwrap_or(0);
                            self.replace_cursor -= prev;
                        }
                    },
                    KeyCode::Right => {
                        if self.replace_cursor < self.replace_input.len() {
                            let next_len = self.replace_input[self.replace_cursor..].chars().next().map(|c| c.len_utf8()).unwrap_or(0);
                            self.replace_cursor += next_len;
                        }
                    },
                    KeyCode::Home => {
                        self.replace_cursor = 0;
                    },
                    KeyCode::End => {
                        self.replace_cursor = self.replace_input.len();
                    },
                    KeyCode::Char(c) => {
                        if self.replace_mode == ReplaceMode::DeleteLine { return; }
                        if !key.modifiers.contains(KeyModifiers::CONTROL) && !key.modifiers.contains(KeyModifiers::ALT) {
                            self.replace_input.insert(self.replace_cursor, c);
                            self.replace_cursor += c.len_utf8();
                        }
                    },
                    _ => {}
                }
            },
            Focus::ResultList => {
                // handle help navigation? but also list navigation
                match key.code {
                    KeyCode::Tab => {
                        self.focus = self.focus.next();
                    },
                    KeyCode::BackTab => {
                        self.focus = self.focus.prev();
                    },
                    KeyCode::Char('j') | KeyCode::Down => {
                        if let Some(exp_idx) = self.expanded_file {
                            // line navigation
                            if exp_idx < self.results.len() {
                                let len = self.results[exp_idx].lines.len();
                                if len > 0 {
                                    if self.selected_line + 1 < len {
                                        self.selected_line += 1;
                                    }
                                }
                            }
                        } else {
                            if !self.results.is_empty() && self.selected_file + 1 < self.results.len() {
                                self.selected_file += 1;
                            }
                        }
                    },
                    KeyCode::Char('k') | KeyCode::Up => {
                        if let Some(exp_idx) = self.expanded_file {
                            if self.selected_line > 0 {
                                self.selected_line -= 1;
                            }
                        } else {
                            if self.selected_file > 0 {
                                self.selected_file -= 1;
                            }
                        }
                    },
                    KeyCode::Char('g') | KeyCode::Char('h') | KeyCode::Left => {
                        // top
                        if self.expanded_file.is_some() {
                            self.selected_line = 0;
                        } else {
                            self.selected_file = 0;
                        }
                    },
                    KeyCode::Char('G') | KeyCode::Char('l') | KeyCode::Right => {
                        // bottom
                        if let Some(exp_idx) = self.expanded_file {
                            if exp_idx < self.results.len() {
                                let len = self.results[exp_idx].lines.len();
                                if len > 0 {
                                    self.selected_line = len - 1;
                                }
                            }
                        } else {
                            if !self.results.is_empty() {
                                self.selected_file = self.results.len() - 1;
                            }
                        }
                    },
                    KeyCode::Enter => {
                        if let Some(exp_idx) = self.expanded_file {
                            // back to list
                            self.expanded_file = None;
                            self.selected_line = 0;
                        } else {
                            // expand file if exists
                            if !self.results.is_empty() {
                                self.expanded_file = Some(self.selected_file);
                                self.selected_line = 0;
                            }
                        }
                    },
                    KeyCode::Char('r') if !key.modifiers.contains(KeyModifiers::CONTROL) => {
                        if let Some(exp_idx) = self.expanded_file {
                            let line_idx = self.selected_line;
                            self.replace_single_line(exp_idx, line_idx);
                        } else {
                            if !self.results.is_empty() {
                                let idx = self.selected_file;
                                self.replace_single_file(idx);
                            }
                        }
                    },
                    KeyCode::Char('d') if !key.modifiers.contains(KeyModifiers::CONTROL) => {
                        if let Some(exp_idx) = self.expanded_file {
                            // delete line from list
                            if exp_idx < self.results.len() {
                                let line_idx = self.selected_line;
                                if line_idx < self.results[exp_idx].lines.len() {
                                    self.results[exp_idx].lines.remove(line_idx);
                                    if self.results[exp_idx].lines.is_empty() {
                                        self.results.remove(exp_idx);
                                        self.expanded_file = None;
                                        self.selected_line = 0;
                                        if self.selected_file >= self.results.len() && self.selected_file > 0 {
                                            self.selected_file -= 1;
                                        }
                                    } else {
                                        if self.selected_line >= self.results[exp_idx].lines.len() && self.selected_line > 0 {
                                            self.selected_line -= 1;
                                        }
                                    }
                                }
                            }
                        } else {
                            if !self.results.is_empty() {
                                self.results.remove(self.selected_file);
                                if self.selected_file >= self.results.len() && self.selected_file > 0 {
                                    self.selected_file -= 1;
                                }
                                // if after remove, expanded? clear
                                self.expanded_file = None;
                            }
                        }
                    },
                    _ => {}
                }
            }
        }
    }
}

fn centered_rect(percent_x: u16, percent_y: u16, r: Rect) -> Rect {
    let popup_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage((100 - percent_y) / 2),
            Constraint::Percentage(percent_y),
            Constraint::Percentage((100 - percent_y) / 2),
        ])
        .split(r);
    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ])
        .split(popup_layout[1])[1]
}

fn ui(f: &mut Frame, app: &mut App) {
    let size = f.area();
    // bottom help bar height 1
    let main_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Min(0), Constraint::Length(1)])
        .split(size);
    let help_area = main_layout[1];
    let main_area = main_layout[0];

    let horizontal = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(35), Constraint::Percentage(65)])
        .split(main_area);
    let left_area = horizontal[0];
    let preview_area = horizontal[1];

    let left_vertical = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Length(3), Constraint::Length(3), Constraint::Min(0)])
        .split(left_area);
    let search_area = left_vertical[0];
    let replace_area = left_vertical[1];
    let result_area = left_vertical[2];

    // Search block
    let search_mode_str = app.search_mode.as_str();
    let search_block = Block::bordered()
        .title(Title::from(" Search ").alignment(Alignment::Left))
        .title(Title::from(format!(" [{}] ", search_mode_str)).alignment(Alignment::Right))
        .border_style(if app.focus == Focus::Search { Style::default().fg(Color::Green) } else { Style::default().fg(Color::White) });
    let search_inner = search_block.inner(search_area);
    f.render_widget(search_block, search_area);
    let p = Paragraph::new(app.search_input.as_str());
    f.render_widget(p, search_inner);
    if app.focus == Focus::Search && !app.show_help && !app.show_confirm {
        f.set_cursor_position((search_inner.x + app.search_cursor as u16, search_inner.y));
    }

    // Replace block
    let replace_mode_str = app.replace_mode.as_str();
    let replace_block = Block::bordered()
        .title(Title::from(" Replace ").alignment(Alignment::Left))
        .title(Title::from(format!(" [{}] ", replace_mode_str)).alignment(Alignment::Right))
        .border_style(if app.focus == Focus::Replace { Style::default().fg(Color::Green) } else { Style::default().fg(Color::White) });
    let replace_inner = replace_block.inner(replace_area);
    f.render_widget(replace_block, replace_area);
    if app.replace_mode == ReplaceMode::DeleteLine {
        let placeholder = Paragraph::new("[Entire line will be deleted]").style(Style::default().fg(Color::DarkGray).italic());
        f.render_widget(placeholder, replace_inner);
    } else {
        let p2 = Paragraph::new(app.replace_input.as_str());
        f.render_widget(p2, replace_inner);
        if app.focus == Focus::Replace && !app.show_help && !app.show_confirm {
            f.set_cursor_position((replace_inner.x + app.replace_cursor as u16, replace_inner.y));
        }
    }

    // Result List
    let result_block = Block::bordered()
        .title(Title::from(" Result List ").alignment(Alignment::Left))
        .border_style(if app.focus == Focus::ResultList { Style::default().fg(Color::Green) } else { Style::default().fg(Color::White) });
    let result_inner = result_block.inner(result_area);
    f.render_widget(result_block, result_area);

    // Determine result display mode
    let mut items: Vec<ListItem> = Vec::new();
    if let Some(exp_idx) = app.expanded_file {
        if exp_idx < app.results.len() {
            let fr = &app.results[exp_idx];
            for (i, lm) in fr.lines.iter().enumerate() {
                let style = if i == app.selected_line { Style::default().bg(Color::DarkGray).fg(Color::White) } else { Style::default() };
                let content = format!("{:>4} {}", lm.number, lm.content);
                items.push(ListItem::new(content).style(style));
            }
        }
    } else {
        for (i, fr) in app.results.iter().enumerate() {
            let style = if i == app.selected_file { Style::default().bg(Color::DarkGray).fg(Color::White) } else { Style::default() };
            let txt = format!("{} ({})", fr.path.display(), fr.lines.len());
            items.push(ListItem::new(txt).style(style));
        }
    }
    let list = List::new(items);
    f.render_widget(list, result_inner);

    // Preview
    let preview_block = Block::bordered()
        .title(Title::from(" Preview ").alignment(Alignment::Left))
        .border_style(Style::default().fg(Color::White));
    let preview_inner = preview_block.inner(preview_area);
    f.render_widget(preview_block, preview_area);

    // Preview content
    if !app.results.is_empty() {
        // Determine file to preview
        let file_idx = if let Some(exp) = app.expanded_file { exp } else { app.selected_file };
        if file_idx < app.results.len() {
            let fr = &app.results[file_idx];
            let abs_path = app.project_root.join(&fr.path);
            if let Ok(content) = fs::read_to_string(&abs_path) {
                // Build preview lines
                let re = app.compile_search_regex();
                let mut preview_lines: Vec<Line> = Vec::new();
                // For each line in file, create styled line
                // We'll show line numbers and highlight matches
                // Also show replacement preview if replace not empty? We'll color replacement
                let mut lines: Vec<&str> = content.lines().collect();
                // If expanded, maybe show only matching lines? But we'll show all lines up to 20 for brevity
                for (idx, line) in lines.iter().enumerate() {
                    let line_no = idx + 1;
                    let mut spans: Vec<Span> = Vec::new();
                    spans.push(Span::styled(format!("{:>4} ", line_no), Style::default().fg(Color::Green)));
                    if let Some(re) = &re {
                        if re.is_match(line) {
                            // highlight matches
                            let mut last = 0;
                            for mat in re.find_iter(line) {
                                if mat.start() > last {
                                    spans.push(Span::raw(line[last..mat.start()].to_string()));
                                }
                                // original match in red strikethrough
                                spans.push(Span::styled(mat.as_str().to_string(), Style::default().fg(Color::White).bg(Color::Red).add_modifier(Modifier::CROSSED_OUT)));
                                // replacement in green
                                if app.replace_mode != ReplaceMode::DeleteLine && !app.replace_input.is_empty() {
                                    let rep = if app.replace_mode == ReplaceMode::PreserveCase {
                                        App::preserve_case(mat.as_str(), &app.replace_input)
                                    } else {
                                        app.replace_input.clone()
                                    };
                                    spans.push(Span::styled(rep, Style::default().fg(Color::White).bg(Color::Green)));
                                }
                                last = mat.end();
                            }
                            if last < line.len() {
                                spans.push(Span::raw(line[last..].to_string()));
                            }
                        } else {
                            spans.push(Span::styled(line.to_string(), Style::default().fg(Color::DarkGray)));
                        }
                    } else {
                        spans.push(Span::raw(line.to_string()));
                    }
                    preview_lines.push(Line::from(spans));
                    if preview_lines.len() > 30 { break; }
                }
                // add separator
                // preview_lines.push(Line::from(Span::styled("--------------------------------------------------------------------------------", Style::default().fg(Color::DarkGray))));
                let para = Paragraph::new(preview_lines);
                f.render_widget(para, preview_inner);
            }
        }
    }

    // Help bar bottom
    let help_text = if app.show_help {
        "Close Help: <Esc> | Next Tab: <Right> | Previous Tab: <Left>"
    } else if app.show_confirm {
        "Confirm Replace: <Enter> | Cancel Replace: <Esc>, Left: <h>, Right: <l>, Loop: <Tab>"
    } else {
        match app.focus {
            Focus::Search => "Help: <Ctrl-b> | Search: <Enter> | Toggle search mode: <Ctrl-n>",
            Focus::Replace => "Help: <Ctrl-b> | Replace: <C-o> | Toggle replace mode: <Ctrl-n>",
            Focus::ResultList => {
                if app.expanded_file.is_some() {
                    "Help: <Ctrl-b> | Back to list: <Enter> | Replace Line: <r> | Next: <j> | Previous: <k> | Top: <g> | Bottom: <G> | Delete line: <d>"
                } else {
                    "Help: <Ctrl-b> | Open File: <Enter> | Replace File: <r> | Next: <j> | Previous: <k> | Top: <g> | Bottom: <G> | Delete file: <d>"
                }
            }
        }
    };
    let help_para = Paragraph::new(help_text).style(Style::default().fg(Color::White));
    f.render_widget(help_para, help_area);

    // Notification
    if let Some((msg, instant)) = &app.notification {
        if instant.elapsed() < Duration::from_secs(3) {
            let notif_area = Rect { x: size.width.saturating_sub(50), y: size.height.saturating_sub(4), width: 45, height: 3 };
            let block = Block::bordered().title(" Notification ").border_style(Style::default().fg(Color::Yellow));
            let inner = block.inner(notif_area);
            f.render_widget(Clear, notif_area);
            f.render_widget(block, notif_area);
            let p = Paragraph::new(msg.as_str()).alignment(Alignment::Center);
            f.render_widget(p, inner);
        }
    }

    // Help dialog
    if app.show_help {
        let area = centered_rect(80, 60, size);
        f.render_widget(Clear, area);
        let block = Block::bordered()
            .title(Title::from(format!(" [1] Global {} [2] Navigation {}Press 'q' to close",
                if app.help_tab==0 {"─"} else {" "},
                if app.help_tab==1 {"─"} else {" "}
            )).alignment(Alignment::Left))
            .border_style(Style::default().fg(Color::Yellow));
        let inner = block.inner(area);
        f.render_widget(block, area);
        let text = if app.help_tab == 0 {
            vec![
                Line::from(""),
                Line::from(" - Ctrl-c: Quit"),
                Line::from(" - Ctrl-d: Quit"),
                Line::from(" - Ctrl-b: Help dialog"),
                Line::from(" - Ctrl-o: Process Replace For All Files"),
                Line::from(" - Ctrl-n: Loop through search and replace modes"),
                Line::from(" - Enter: Select/Deselect file"),
                Line::from(" - d: delete file/delete line from the replace process"),
                Line::from(" - r: Replace Selected File Or Line"),
            ]
        } else {
            vec![
                Line::from(""),
                Line::from(" - Tab: Loop through panes"),
                Line::from(" - j/UpArrow: Move up"),
                Line::from(" - k/DownArrow: Move down"),
                Line::from(" - h/g/LeftArrow: Move to Top"),
                Line::from(" - l/G/RightArrow: Move to Bottom"),
            ]
        };
        let para = Paragraph::new(text);
        f.render_widget(para, inner);
    }

    // Confirm dialog
    if app.show_confirm {
        let area = centered_rect(60, 30, size);
        f.render_widget(Clear, area);
        let block = Block::bordered().title(" Confirm Dialog ").border_style(Style::default().fg(Color::Red));
        let inner = block.inner(area);
        f.render_widget(block, area);
        let msg = if app.confirm_is_empty_replace {
            "Replace text is empty, and replacing with an empty string will remove the matched text.\nAre you sure you want to continue?"
        } else {
            "This action will modify the files in this directory.\nAre you sure you want to continue?"
        };
        let chunks = Layout::default()
            .direction(Direction::Vertical)
            .constraints([Constraint::Min(4), Constraint::Length(1)])
            .split(inner);
        let para = Paragraph::new(msg).alignment(Alignment::Center);
        f.render_widget(para, chunks[0]);
        let buttons = if app.confirm_selection == 0 {
            Line::from(vec![
                Span::styled(" Continue ", Style::default().bg(Color::Blue).fg(Color::White)),
                Span::raw("  "),
                Span::styled(" Cancel ", Style::default().fg(Color::White)),
            ])
        } else {
            Line::from(vec![
                Span::styled(" Continue ", Style::default().fg(Color::White)),
                Span::raw("  "),
                Span::styled(" Cancel ", Style::default().bg(Color::Blue).fg(Color::White)),
            ])
        };
        let btn_para = Paragraph::new(buttons).alignment(Alignment::Center);
        f.render_widget(btn_para, chunks[1]);
    }
}

fn run_tui(project_root: PathBuf) -> anyhow::Result<()> {
    enable_raw_mode().context("failed to enable raw mode")?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen).context("enter alt screen")?;
    let backend = ratatui::backend::CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend).context("create terminal")?;

    let mut app = App::new(project_root);

    loop {
        terminal.draw(|f| ui(f, &mut app)).context("draw")?;
        // handle notification timeout without blocking event
        if event::poll(Duration::from_millis(100)).context("poll")? {
            if let Event::Key(key) = event::read().context("read event")? {
                if key.kind == KeyEventKind::Press || key.kind == KeyEventKind::Repeat {
                    app.handle_key(key);
                    if app.should_quit {
                        break;
                    }
                }
            }
        }
        if let Some((_, instant)) = &app.notification {
            if instant.elapsed() > Duration::from_secs(3) {
                app.notification = None;
            }
        }
    }

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;
    Ok(())
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    // manual parsing for help/version and project-root
    let mut project_root = String::from(".");
    let mut help_flag = false;
    let mut version_flag = false;
    let mut i = 1;
    let mut error: Option<String> = None;
    let mut unknown_arg: Option<String> = None;
    while i < args.len() {
        let arg = &args[i];
        if arg == "--help" || arg == "-h" {
            help_flag = true;
            i += 1;
            // continue to check but help takes precedence, still need to detect unknown? but we ignore
            // Actually we should not error if help present; just print help
            // Skip remaining?
            // Let's just set flag and continue scanning for unknown to ignore?
            // We'll just break after known help as per original: extra args ignored
            // So we can continue but ignore errors
            continue;
        } else if arg == "--version" || arg == "-V" {
            version_flag = true;
            i += 1;
            continue;
        } else if arg == "--project-root" || arg == "-p" {
            if i + 1 >= args.len() {
                error = Some(format!("error: a value is required for '--project-root <PATH>' but none was supplied\n\nFor more information, try '--help'."));
                break;
            }
            project_root = args[i+1].clone();
            i += 2;
            continue;
        } else if arg.starts_with("--project-root=") {
            let val = arg.trim_start_matches("--project-root=").to_string();
            if val.is_empty() {
                error = Some(format!("error: a value is required for '--project-root <PATH>' but none was supplied\n\nFor more information, try '--help'."));
                break;
            }
            project_root = val;
            i += 1;
            continue;
        } else if arg.starts_with("-p=") {
            let val = arg.trim_start_matches("-p=").to_string();
            project_root = val;
            i += 1;
            continue;
        } else if arg.starts_with("-") {
            // unknown flag
            if help_flag || version_flag {
                // if help/version present, ignore unknown? But original with --help and --project-root had help precedence, unknown with help maybe still help?
                // For unknown without help, error
                unknown_arg = Some(arg.clone());
            } else {
                unknown_arg = Some(arg.clone());
            }
            i += 1;
            // don't break; collect
            continue;
        } else {
            // positional
            unknown_arg = Some(arg.clone());
            i += 1;
            continue;
        }
    }

    if help_flag {
        print_help();
        std::process::exit(0);
    }
    if version_flag {
        print_version();
        std::process::exit(0);
    }
    if let Some(msg) = error {
        eprintln!("{}", msg);
        std::process::exit(2);
    }
    if let Some(unk) = unknown_arg {
        eprintln!("error: unexpected argument '{}' found", unk);
        eprintln!();
        eprintln!("Usage: executable [OPTIONS]");
        eprintln!();
        eprintln!("For more information, try '--help'.");
        std::process::exit(2);
    }

    let proj_path = PathBuf::from(project_root);
    // Note: we don't error if project_root doesn't exist; TUI will handle empty

    // Try to read config (ignore errors)
    // Config reading is not critical for functionality, but we attempt
    let _config_path = dirs::config_dir().map(|p| p.join("serpl").join("config.json5"));
    // we could try to parse; ignoring for now

    if let Err(e) = run_tui(proj_path) {
        eprintln!("serpl error: Something went wrong");
        eprintln!("Error: ");
        eprintln!("   0: {}", format!("{}", e).red());
        std::process::exit(1);
    }
}
RS
"}

