#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SearchMode {
    Simple,
    MatchCase,
    MatchWholeWord,
    MatchCaseWholeWord,
    Regex,
}
impl SearchMode {
    fn next(self) -> Self {
        match self {
            SearchMode::Simple => SearchMode::MatchCase,
            SearchMode::MatchCase => SearchMode::MatchWholeWord,
            SearchMode::MatchWholeWord => SearchMode::MatchCaseWholeWord,
            SearchMode::MatchCaseWholeWord => SearchMode::Regex,
            SearchMode::Regex => SearchMode::Simple,
        }
    }
    fn as_str(self) -> &'static str {
        match self {
            SearchMode::Simple => "Simple",
            SearchMode::MatchCase => "Match Case",
            SearchMode::MatchWholeWord => "Match Whole Word",
            SearchMode::MatchCaseWholeWord => "Match Case Whole Word",
            SearchMode::Regex => "Regex",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ReplaceMode {
    Simple,
    PreserveCase,
    DeleteLine,
}
impl ReplaceMode {
    fn next(self) -> Self {
        match self {
            ReplaceMode::Simple => ReplaceMode::PreserveCase,
            ReplaceMode::PreserveCase => ReplaceMode::DeleteLine,
            ReplaceMode::DeleteLine => ReplaceMode::Simple,
        }
    }
    fn as_str(self) -> &'static str {
        match self {
            ReplaceMode::Simple => "Simple",
            ReplaceMode::PreserveCase => "Preserve Case",
            ReplaceMode::DeleteLine => "Delete Line",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Focus {
    Search,
    Replace,
    ResultList,
}
impl Focus {
    fn next(self) -> Self {
        match self {
            Focus::Search => Focus::Replace,
            Focus::Replace => Focus::ResultList,
            Focus::ResultList => Focus::Search,
        }
    }
    fn prev(self) -> Self {
        match self {
            Focus::Search => Focus::ResultList,
            Focus::Replace => Focus::Search,
            Focus::ResultList => Focus::Replace,
        }
    }
}

#[derive(Debug, Clone)]
struct LineMatch {
    number: usize,
    content: String,
}

#[derive(Debug, Clone)]
struct FileResult {
    path: PathBuf, // relative
    lines: Vec<LineMatch>,
}

struct App {
    project_root: PathBuf,
    search_input: String,
    search_cursor: usize,
    replace_input: String,
    replace_cursor: usize,
    search_mode: SearchMode,
    replace_mode: ReplaceMode,
    focus: Focus,
    results: Vec<FileResult>,
    selected_file: usize,
    // when Some(idx), we are showing lines of that file
    expanded_file: Option<usize>,
    selected_line: usize,
    show_help: bool,
    help_tab: usize, // 0 global, 1 navigation
    show_confirm: bool,
    confirm_is_empty_replace: bool,
    confirm_selection: usize, // 0 continue, 1 cancel
    notification: Option<(String, Instant)>,
    should_quit: bool,
}

impl App {
    fn new(project_root: PathBuf) -> Self {
        Self {
            project_root,
            search_input: String::new(),
            search_cursor: 0,
            replace_input: String::new(),
            replace_cursor: 0,
            search_mode: SearchMode::Simple,
            replace_mode: ReplaceMode::Simple,
            focus: Focus::Search,
            results: Vec::new(),
            selected_file: 0,
            expanded_file: None,
            selected_line: 0,
            show_help: false,
            help_tab: 0,
            show_confirm: false,
            confirm_is_empty_replace: false,
            confirm_selection: 0,
            notification: None,
            should_quit: false,
        }
    }

    fn compile_search_regex(&self) -> Option<Regex> {
        let pat = self.search_input.as_str();
        if pat.is_empty() {
            return None;
        }
        let regex_str = match self.search_mode {
            SearchMode::Simple => format!("(?i){}", regex::escape(pat)),
            SearchMode::MatchCase => regex::escape(pat),
            SearchMode::MatchWholeWord => format!("(?i)\\b{}\\b", regex::escape(pat)),
            SearchMode::MatchCaseWholeWord => format!("\\b{}\\b", regex::escape(pat)),
            SearchMode::Regex => pat.to_string(),
        };
        Regex::new(&regex_str).ok()
    }

    fn perform_search(&mut self) {
        self.results.clear();
        self.selected_file = 0;
        self.expanded_file = None;
        self.selected_line = 0;
        if self.search_input.is_empty() {
            return;
        }
        let re = match self.compile_search_regex() {
            Some(r) => r,
            None => return, // invalid regex => no results
        };
        let walker = ignore::WalkBuilder::new(&self.project_root)
            .hidden(true)
            .git_ignore(true)
            .git_global(true)
            .git_exclude(true)
            .parents(true)
            .follow_links(false)
            .build();
        let mut results = Vec::new();
        for entry in walker {
            let entry = match entry {
                Ok(e) => e,
                Err(_) => continue,
            };
            if !entry.file_type().map(|ft| ft.is_file()).unwrap_or(false) {
                continue;
            }
            let path = entry.path();
            // read file
            let content = match fs::read_to_string(path) {
                Ok(c) => c,
                Err(_) => continue,
            };
            if content.contains('\0') {
                continue;
            }
            let mut line_matches = Vec::new();
            for (idx, line) in content.lines().enumerate() {
                if re.is_match(line) {
                    line_matches.push(LineMatch { number: idx+1, content: line.to_string() });
                }
            }
            if !line_matches.is_empty() {
                let rel = path.strip_prefix(&self.project_root).unwrap_or(path).to_path_buf();
                results.push(FileResult { path: rel, lines: line_matches });
            }
        }
        results.sort_by(|a,b| a.path.cmp(&b.path));
        self.results = results;
        // clamp selection
        if self.selected_file >= self.results.len() && !self.results.is_empty() {
            self.selected_file = self.results.len()-1;
        }
    }

    fn preserve_case(orig: &str, rep: &str) -> String {
        if orig.is_empty() || rep.is_empty() {
            return rep.to_string();
        }
        let is_all_upper = orig.chars().filter(|c| c.is_alphabetic()).all(|c| c.is_uppercase()) && orig.chars().any(|c| c.is_alphabetic());
        if is_all_upper {
            return rep.to_uppercase();
        }
        let mut chars = orig.chars();
        let first = chars.next().unwrap();
        let rest = &orig[first.len_utf8()..];
        let is_capitalized = first.is_uppercase() && rest.chars().filter(|c| c.is_alphabetic()).all(|c| c.is_lowercase());
        if is_capitalized {
            let mut rep_chars = rep.chars();
            if let Some(f) = rep_chars.next() {
                let first_up: String = f.to_uppercase().collect();
                let rest_low = rep_chars.as_str().to_lowercase();
                return format!("{}{}", first_up, rest_low);
            } else {
                return String::new();
            }
        }
        // default lower
        // if orig is all lower, keep rep as is (lower)
        // we return rep as is if it's already lower? But we normalize to lower to handle "hi" vs "HELLO"
        // If rep is lower, fine. If rep is mixed, we return lower?
        // For simplicity, if orig is lower, return rep as is (but lowercased if needed)
        // The observed behavior for "hello" -> "hi" produced "hi" lower, so return rep as is (assuming rep is lower)
        // We'll return rep.to_string() if orig is lower
        // But to be safe, return rep as is
        rep.to_string()
    }

    fn apply_replace_to_content(&self, content: &str) -> String {
        if self.search_input.is_empty() {
            return content.to_string();
        }
        let re = match self.compile_search_regex() {
            Some(r) => r,
            None => return content.to_string(),
        };
        match self.replace_mode {
            ReplaceMode::DeleteLine => {
                let mut out_lines = Vec::new();
                for line in content.lines() {
                    if !re.is_match(line) {
                        out_lines.push(line);
                    }
                }
                let mut out = out_lines.join("\n");
                if content.ends_with('\n') && !out.is_empty() {
                    out.push('\n');
                } else if content.is_empty() {
                    out = String::new();
                }
                // handle case where original had no newline but we joined with \n
                out
            },
            ReplaceMode::Simple => {
                let mut result = String::new();
                let mut last = 0;
                for mat in re.find_iter(content) {
                    result.push_str(&content[last..mat.start()]);
                    result.push_str(&self.replace_input);
                    last = mat.end();
                }
                result.push_str(&content[last..]);
                result
            },
            ReplaceMode::PreserveCase => {
                let mut result = String::new();
                let mut last = 0;
                for mat in re.find_iter(content) {
                    result.push_str(&content[last..mat.start()]);
                    let orig = mat.as_str();
                    let rep = Self::preserve_case(orig, &self.replace_input);
                    result.push_str(&rep);
                    last = mat.end();
                }
                result.push_str(&content[last..]);
                result
            }
        }
    }

    fn global_replace(&mut self) {
        // Check if search empty -> do nothing
        if self.search_input.is_empty() {
            return;
        }
        // if replace empty and mode not DeleteLine, we already have confirm
        let mut success_count = 0;
        // clone results to avoid borrow issues
        let results_clone = self.results.clone();
        for fr in &results_clone {
            let abs_path = self.project_root.join(&fr.path);
            let content = match fs::read_to_string(&abs_path) {
                Ok(c) => c,
                Err(_) => continue,
            };
            let new_content = self.apply_replace_to_content(&content);
            if new_content != content {
                if let Err(_) = fs::write(&abs_path, new_content) {
                    continue;
                }
                success_count += 1;
            }
        }
        // after global replace, clear inputs and results as observed
        self.search_input.clear();
        self.search_cursor = 0;
        self.replace_input.clear();
        self.replace_cursor = 0;
        self.results.clear();
        self.selected_file = 0;
        self.expanded_file = None;
        self.selected_line = 0;
        self.notification = Some(("Search and replace completed successfully".to_string(), Instant::now()));
        self.show_confirm = false;
    }

    fn replace_single_file(&mut self, idx: usize) {
        if idx >= self.results.len() { return; }
        let fr = self.results[idx].clone();
        let abs_path = self.project_root.join(&fr.path);
        let content = match fs::read_to_string(&abs_path) {
            Ok(c) => c,
            Err(_) => return,
        };
        let new_content = self.apply_replace_to_content(&content);
        if new_content != content {
            let _ = fs::write(&abs_path, new_content);
        }
        // remove from results or refresh
        self.results.remove(idx);
        if self.selected_file >= self.results.len() && self.selected_file > 0 {
            self.selected_file -= 1;
        }
        self.expanded_file = None;
        self.selected_line = 0;
        self.notification = Some(("File replacement completed successfully".to_string(), Instant::now()));
        // if after removal we have no results, stay
    }

    fn replace_single_line(&mut self, file_idx: usize, line_idx: usize) {
        if file_idx >= self.results.len() { return; }
        let fr = self.results[file_idx].clone();
        if line_idx >= fr.lines.len() { return; }
        let line_match = fr.lines[line_idx].clone();
        let abs_path = self.project_root.join(&fr.path);
        let content = match fs::read_to_string(&abs_path) {
            Ok(c) => c,
            Err(_) => return,
        };
        // For DeleteLine mode, we need to delete that line entirely (matching line)
        // Otherwise replace occurrences within that line only
        let re = match self.compile_search_regex() {
            Some(r) => r,
            None => return,
        };
        let mut lines: Vec<String> = content.lines().map(|s| s.to_string()).collect();
        let has_trailing_newline = content.ends_with('\n');
        // line numbers are 1-indexed
        let target_idx = line_match.number - 1;
        if target_idx >= lines.len() { return; }
        match self.replace_mode {
            ReplaceMode::DeleteLine => {
                lines.remove(target_idx);
            },
            ReplaceMode::Simple => {
                let line = &lines[target_idx];
                let mut new_line = String::new();
                let mut last = 0;
                for mat in re.find_iter(line) {
                    new_line.push_str(&line[last..mat.start()]);
                    new_line.push_str(&self.replace_input);
                    last = mat.end();
                }
                new_line.push_str(&line[last..]);
                lines[target_idx] = new_line;
            },
            ReplaceMode::PreserveCase => {
                let line = &lines[target_idx];
                let mut new_line = String::new();
                let mut last = 0;
                for mat in re.find_iter(line) {
                    new_line.push_str(&line[last..mat.start()]);
                    let rep = Self::preserve_case(mat.as_str(), &self.replace_input);
                    new_line.push_str(&rep);
                    last = mat.end();
                }
                new_line.push_str(&line[last..]);
                lines[target_idx] = new_line;
            }
        }
        let mut new_content = lines.join("\n");
        if has_trailing_newline && !new_content.is_empty() {
            new_content.push('\n');
        }
        let _ = fs::write(&abs_path, new_content);
        // Update results: remove that line
        self.results[file_idx].lines.remove(line_idx);
        if self.results[file_idx].lines.is_empty() {
            self.results.remove(file_idx);
            self.expanded_file = None;
            self.selected_line = 0;
            if self.selected_file >= self.results.len() && self.selected_file > 0 {
                self.selected_file -= 1;
            }
        } else {
            if self.selected_line >= self.results[file_idx].lines.len() && self.selected_line > 0 {
                self.selected_line -= 1;
            }
        }
        self.notification = Some(("Line replacement completed successfully".to_string(), Instant::now()));
    }

    fn handle_key(&mut self, key: event::KeyEvent) {
        // Global handling when help shown
        if self.show_help {
            match key.code {
                KeyCode::Esc | KeyCode::Char('q') | KeyCode::Char('Q') => {
                    self.show_help = false;
                    return;
                },
                KeyCode::Right | KeyCode::Tab => {
                    self.help_tab = (self.help_tab + 1) % 2;
                    return;
                },
                KeyCode::Left | KeyCode::BackTab => {
                    self.help_tab = if self.help_tab == 0 { 1 } else { 0 };
                    return;
                },
                _ => return,
            }
        }
        if self.show_confirm {
            match key.code {
                KeyCode::Esc => {
                    self.show_confirm = false;
                    return;
                },
                KeyCode::Enter => {
                    if self.confirm_selection == 0 {
                        self.global_replace();
                    } else {
                        self.show_confirm = false;
                    }
                    return;
                },
                KeyCode::Left | KeyCode::Char('h') if key.modifiers.is_empty() => {
                    self.confirm_selection = if self.confirm_selection == 0 { 1 } else { 0 };
                    return;
                },
                KeyCode::Right | KeyCode::Char('l') if key.modifiers.is_empty() => {
                    self.confirm_selection = if self.confirm_selection == 0 { 1 } else { 0 };
                    return;
                },
                KeyCode::Tab => {
                    self.confirm_selection = 1 - self.confirm_selection;
                    return;
                },
                KeyCode::BackTab => {
                    self.confirm_selection = 1 - self.confirm_selection;
                    return;
                },
                KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.should_quit = true;
                    return;
                },
                KeyCode::Char('d') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.should_quit = true;
                    return;
                },
                _ => return,
            }
        }

        // Global shortcuts
        if key.modifiers.contains(KeyModifiers::CONTROL) {
            match key.code {
                KeyCode::Char('c') | KeyCode::Char('d') => {
                    self.should_quit = true;
                    return;
                },
                KeyCode::Char('z') => {
                    // suspend
                    // We will handle suspend outside via flag? For now do inline disable
                    // To suspend, we need to leave raw mode; we'll set a flag and handle in main loop
                    // For simplicity, try to suspend here
                    let _ = disable_raw_mode();
                    let _ = execute!(io::stdout(), LeaveAlternateScreen);
                    let _ = nix::sys::signal::raise(nix::sys::signal::Signal::SIGTSTP);
                    let _ = enable_raw_mode();
                    let _ = execute!(io::stdout(), EnterAlternateScreen);
                    return;
                },
                KeyCode::Char('r') => {
                    self.perform_search();
                    return;
                },
                KeyCode::Char('o') => {
                    if !self.search_input.is_empty() {
                        // check if replace empty and mode not DeleteLine
                        if self.replace_input.is_empty() && self.replace_mode != ReplaceMode::DeleteLine {
                            self.confirm_is_empty_replace = true;
                        } else {
                            self.confirm_is_empty_replace = false;
                        }
                        self.show_confirm = true;
                        self.confirm_selection = 0;
                    }
                    return;
                },
                KeyCode::Char('b') => {
                    self.show_help = true;
                    self.help_tab = 0;
                    return;
                },
                KeyCode::Char('n') => {
                    match self.focus {
                        Focus::Search => {
                            self.search_mode = self.search_mode.next();
                            self.perform_search();
                        },
                        Focus::Replace => {
                            self.replace_mode = self.replace_mode.next();
                            // if switching to DeleteLine, maybe clear? But keep input
                        },
                        Focus::ResultList => {
                            // maybe do nothing? Original Ctrl-n when in ResultList does nothing? In earlier test it stayed same.
                        }
                    }
                    return;
                },
                _ => {}
            }
        }

        match self.focus {
            Focus::Search => {
                match key.code {
                    KeyCode::Tab => {
                        self.focus = self.focus.next();
                    },
                    KeyCode::BackTab => {
                        self.focus = self.focus.prev();
                    },
                    KeyCode::Enter => {
                        self.perform_search();
                    },
                    KeyCode::Backspace => {
                        if self.search_cursor > 0 {
                            let prev = self.search_input[..self.search_cursor].chars().next_back().map(|c| c.len_utf8()).unwrap_or(0);
                            let remove_at = self.search_cursor - prev;
                            self.search_input.remove(remove_at);
                            self.search_cursor = remove_at;
                            self.perform_search();
                        }
                    },
                    KeyCode::Delete => {
                        if self.search_cursor < self.search_input.len() {
                            let next_len = self.search_input[self.search_cursor..].chars().next().map(|c| c.len_utf8()).unwrap_or(0);
                            self.search_input.drain(self.search_cursor..self.search_cursor+next_len);
                            self.perform_search();
                        }
                    },
                    KeyCode::Left => {
                        if self.search_cursor > 0 {
                            let prev = self.search_input[..self.search_cursor].chars().next_back().map(|c| c.len_utf8()).unwrap_or(0);
                            self.search_cursor -= prev;
                        }
                    },
                    KeyCode::Right => {
                        if self.search_cursor < self.search_input.len() {
                            let next_len = self.search_input[self.search_cursor..].chars().next().map(|c| c.len_utf8()).unwrap_or(0);
                            self.search_cursor += next_len;
                        }
                    },
                    KeyCode::Home => {
                        self.search_cursor = 0;
                    },
                    KeyCode::End => {
                        self.search_cursor = self.search_input.len();
                    },
                    KeyCode::Char(c) => {
                        // ignore if ctrl
                        if !key.modifiers.contains(KeyModifiers::CONTROL) && !key.modifiers.contains(KeyModifiers::ALT) {
                            self.search_input.insert(self.search_cursor, c);
                            self.search_cursor += c.len_utf8();
                            self.perform_search();
                        }
                    },
                    KeyCode::Esc => {
                        // maybe clear? Not needed
                    },
                    _ => {}
                }
            },
            Focus::Replace => {
                match key.code {
                    KeyCode::Tab => {
                        self.focus = self.focus.next();
                    },
                    KeyCode::BackTab => {
                        self.focus = self.focus.prev();
                    },
                    KeyCode::Backspace => {
                        if self.replace_mode == ReplaceMode::DeleteLine {
                            return;
                        }
                        if self.replace_cursor > 0 {
                            let prev = self.replace_input[..self.replace_cursor].chars().next_back().map(|c| c.len_utf8()).unwrap_or(0);
                            let remove_at = self.replace_cursor - prev;
                            self.replace_input.remove(remove_at);
                            self.replace_cursor = remove_at;
                        }
                    },
                    KeyCode::Delete => {
                        if self.replace_mode == ReplaceMode::DeleteLine { return; }
                        if self.replace_cursor < self.replace_input.len() {
                            let next_len = self.replace_input[self.replace_cursor..].chars().next().map(|c| c.len_utf8()).unwrap_or(0);
                            self.replace_input.drain(self.replace_cursor..self.replace_cursor+next_len);
                        }
                    },
                    KeyCode::Left => {
                        if self.replace_cursor > 0 {
                            let prev = self.replace_input[..self.replace_cursor].chars().next_back().map(|c| c.len_utf8()).unwrap_or(0);
                            self.replace_cursor -= prev;
                        }
                    },
                    KeyCode::Right => {
                        if self.replace_cursor < self.replace_input.len() {
                            let next_len = self.replace_input[self.replace_cursor..].chars().next().map(|c| c.len_utf8()).unwrap_or(0);
                            self.replace_cursor += next_len;
                        }
                    },
                    KeyCode::Home => {
                        self.replace_cursor = 0;
                    },
                    KeyCode::End => {
                        self.replace_cursor = self.replace_input.len();
                    },
                    KeyCode::Char(c) => {
                        if self.replace_mode == ReplaceMode::DeleteLine { return; }
                        if !key.modifiers.contains(KeyModifiers::CONTROL) && !key.modifiers.contains(KeyModifiers::ALT) {
                            self.replace_input.insert(self.replace_cursor, c);
                            self.replace_cursor += c.len_utf8();
                        }
                    },
                    _ => {}
                }
            },
            Focus::ResultList => {
                // handle help navigation? but also list navigation
                match key.code {
                    KeyCode::Tab => {
                        self.focus = self.focus.next();
                    },
                    KeyCode::BackTab => {
                        self.focus = self.focus.prev();
                    },
                    KeyCode::Char('j') | KeyCode::Down => {
                        if let Some(exp_idx) = self.expanded_file {
                            // line navigation
                            if exp_idx < self.results.len() {
                                let len = self.results[exp_idx].lines.len();
                                if len > 0 {
                                    if self.selected_line + 1 < len {
                                        self.selected_line += 1;
                                    }
                                }
                            }
                        } else {
                            if !self.results.is_empty() && self.selected_file + 1 < self.results.len() {
                                self.selected_file += 1;
                            }
                        }
                    },
                    KeyCode::Char('k') | KeyCode::Up => {
                        if let Some(exp_idx) = self.expanded_file {
                            if self.selected_line > 0 {
                                self.selected_line -= 1;
                            }
                        } else {
                            if self.selected_file > 0 {
                                self.selected_file -= 1;
                            }
                        }
                    },
                    KeyCode::Char('g') | KeyCode::Char('h') | KeyCode::Left => {
                        // top
                        if self.expanded_file.is_some() {
                            self.selected_line = 0;
                        } else {
                            self.selected_file = 0;
                        }
                    },
                    KeyCode::Char('G') | KeyCode::Char('l') | KeyCode::Right => {
                        // bottom
                        if let Some(exp_idx) = self.expanded_file {
                            if exp_idx < self.results.len() {
                                let len = self.results[exp_idx].lines.len();
                                if len > 0 {
                                    self.selected_line = len - 1;
                                }
                            }
                        } else {
                            if !self.results.is_empty() {
                                self.selected_file = self.results.len() - 1;
                            }
                        }
                    },
                    KeyCode::Enter => {
                        if let Some(exp_idx) = self.expanded_file {
                            // back to list
                            self.expanded_file = None;
                            self.selected_line = 0;
                        } else {
                            // expand file if exists
                            if !self.results.is_empty() {
                                self.expanded_file = Some(self.selected_file);
                                self.selected_line = 0;
                            }
                        }
                    },
                    KeyCode::Char('r') if !key.modifiers.contains(KeyModifiers::CONTROL) => {
                        if let Some(exp_idx) = self.expanded_file {
                            let line_idx = self.selected_line;
                            self.replace_single_line(exp_idx, line_idx);
                        } else {
                            if !self.results.is_empty() {
                                let idx = self.selected_file;
                                self.replace_single_file(idx);
                            }
                        }
                    },
                    KeyCode::Char('d') if !key.modifiers.contains(KeyModifiers::CONTROL) => {
                        if let Some(exp_idx) = self.expanded_file {
                            // delete line from list
                            if exp_idx < self.results.len() {
                                let line_idx = self.selected_line;
                                if line_idx < self.results[exp_idx].lines.len() {
                                    self.results[exp_idx].lines.remove(line_idx);
                                    if self.results[exp_idx].lines.is_empty() {
                                        self.results.remove(exp_idx);
                                        self.expanded_file = None;
                                        self.selected_line = 0;
                                        if self.selected_file >= self.results.len() && self.selected_file > 0 {
                                            self.selected_file -= 1;
                                        }
                                    } else {
                                        if self.selected_line >= self.results[exp_idx].lines.len() && self.selected_line > 0 {
                                            self.selected_line -= 1;
                                        }
                                    }
                                }
                            }
                        } else {
                            if !self.results.is_empty() {
                                self.results.remove(self.selected_file);
                                if self.selected_file >= self.results.len() && self.selected_file > 0 {
                                    self.selected_file -= 1;
                                }
                                // if after remove, expanded? clear
                                self.expanded_file = None;
                            }
                        }
                    },
                    _ => {}
                }
            }
        }
    }
}

fn centered_rect(percent_x: u16, percent_y: u16, r: Rect) -> Rect {
    let popup_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage((100 - percent_y) / 2),
            Constraint::Percentage(percent_y),
            Constraint::Percentage((100 - percent_y) / 2),
        ])
        .split(r);
    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ])
        .split(popup_layout[1])[1]
}

fn ui(f: &mut Frame, app: &mut App) {
    let size = f.area();
    // bottom help bar height 1
    let main_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Min(0), Constraint::Length(1)])
        .split(size);
    let help_area = main_layout[1];
    let main_area = main_layout[0];

    let horizontal = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(35), Constraint::Percentage(65)])
        .split(main_area);
    let left_area = horizontal[0];
    let preview_area = horizontal[1];

    let left_vertical = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Length(3), Constraint::Length(3), Constraint::Min(0)])
        .split(left_area);
    let search_area = left_vertical[0];
    let replace_area = left_vertical[1];
    let result_area = left_vertical[2];

    // Search block
    let search_mode_str = app.search_mode.as_str();
    let search_block = Block::bordered()
        .title(Title::from(" Search ").alignment(Alignment::Left))
        .title(Title::from(format!(" [{}] ", search_mode_str)).alignment(Alignment::Right))
        .border_style(if app.focus == Focus::Search { Style::default().fg(Color::Green) } else { Style::default().fg(Color::White) });
