#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SearchMode { Simple, MatchCase, MatchWholeWord, MatchCaseWholeWord, Regex }
impl SearchMode {
    fn next(self) -> Self { match self { SearchMode::Simple=>SearchMode::MatchCase, SearchMode::MatchCase=>SearchMode::MatchWholeWord, SearchMode::MatchWholeWord=>SearchMode::MatchCaseWholeWord, SearchMode::MatchCaseWholeWord=>SearchMode::Regex, SearchMode::Regex=>SearchMode::Simple } }
    fn as_str(self)->&'static str{ match self{ SearchMode::Simple=>"Simple", SearchMode::MatchCase=>"Match Case", SearchMode::MatchWholeWord=>"Match Whole Word", SearchMode::MatchCaseWholeWord=>"Match Case Whole Word", SearchMode::Regex=>"Regex"} }
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ReplaceMode { Simple, PreserveCase, DeleteLine }
impl ReplaceMode {
    fn next(self)->Self{ match self{ ReplaceMode::Simple=>ReplaceMode::PreserveCase, ReplaceMode::PreserveCase=>ReplaceMode::DeleteLine, ReplaceMode::DeleteLine=>ReplaceMode::Simple } }
    fn as_str(self)->&'static str{ match self{ ReplaceMode::Simple=>"Simple", ReplaceMode::PreserveCase=>"Preserve Case", ReplaceMode::DeleteLine=>"Delete Line"} }
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Focus { Search, Replace, ResultList }
impl Focus{ fn next(self)->Self{ match self{ Focus::Search=>Focus::Replace, Focus::Replace=>Focus::ResultList, Focus::ResultList=>Focus::Search } } fn prev(self)->Self{ match self{ Focus::Search=>Focus::ResultList, Focus::Replace=>Focus::Search, Focus::ResultList=>Focus::Replace } } }

#[derive(Debug, Clone)]
struct LineMatch { number: usize, content: String }
