#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Focus { Search, Replace, ResultList }
impl Focus{ fn next(self)->Self{ match self{ Focus::Search=>Focus::Replace, Focus::Replace=>Focus::ResultList, Focus::ResultList=>Focus::Search } } fn prev(self)->Self{ match self{ Focus::Search=>Focus::ResultList, Focus::Replace=>Focus::Search, Focus::ResultList=>Focus::Replace } } }

