    let p=Paragraph::new(app.search_input.as_str());
    f.render_widget(p, search_inner);
    if app.focus==Focus::Search && !app.show_help && !app.show_confirm{ f.set_cursor_position((search_inner.x + app.search_cursor as u16, search_inner.y)); }
    let replace_mode_str=app.replace_mode.as_str();
