    }
    let result_block=Block::bordered().title_top(Line::from(" Result List ").alignment(Alignment::Left)).border_style(if app.focus==Focus::ResultList{Style::default().fg(Color::Green)}else{Style::default().fg(Color::White)});
    let result_inner=result_block.inner(result_area);
